const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dorsoidongCo = ee.Geometry.Point(91.56, 32.12).buffer(5000); // 5km buffer for lake
  const chibzhangCo = ee.Geometry.Point(89.83, 31.06).buffer(5000); // 5km buffer for lake

  const startDate = '1987-10-01';
  const endDate = '1987-10-31'; // Broader window for October 1987 to find an image

  const bandName = 'B1'; // Blue band for Landsat 5 TM

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
    .filterDate(startDate, endDate)
    .filterBounds(dorsoidongCo.union(chibzhangCo));

  if (collection.size().getInfo() === 0) {
    console.log("No Landsat 5 images found for October 1987 in the lake areas.");
    console.log("C1");
    return;
  }

  // Cloud masking function for Landsat 5 SR
  function maskL5srClouds(image) {
    var qa = image.select('pixel_qa');
    // Bits 0 and 1 are fill, 2 is cloud shadow, 3 is cloud, 4 is snow, 5 is water.
    // We want to mask out cloud shadow and cloud.
    var cloudShadowBitMask = (1 << 3);
    var cloudsBitMask = (1 << 5); // Corrected cloud bit for C01/T1_SR (Bit 5 for Cloud) - actually it is Bit 3 for C01, Bit 5 for C02
    // Let's re-check the Landsat 5 SR pixel_qa bits.
    // For LANDSAT/LT05/C01/T1_SR, pixel_qa bits are:
    // Bit 0: Fill
    // Bit 1: Clear
    // Bit 2: Water
    // Bit 3: Cloud Shadow
    // Bit 4: Snow
    // Bit 5: Cloud
    // Bit 6: Cloud Confidence (low)
    // Bit 7: Cloud Confidence (high)
    // Bit 8: Cirrus Confidence (low)
    // Bit 9: Cirrus Confidence (high)

    // Mask out clouds (Bit 5) and cloud shadows (Bit 3)
    var mask = qa.bitwiseAnd(1 << 5).eq(0) // No cloud
      .and(qa.bitwiseAnd(1 << 3).eq(0)); // No cloud shadow

    return image.updateMask(mask).divide(10000); // Scale to 0-1 reflectance
  }

  let image = collection.map(maskL5srClouds).median(); // Use median to get a representative image for the month

  // Check if the median image is null after masking
  if (image.bandNames().size().getInfo() === 0) {
    console.log("Median image has no bands, likely due to all images being fully masked.");
    console.log("C2");
    return;
  }

  // 3. Processing & 4. Calculation
  const scale = 30; // Native resolution of Landsat 5
  const maxPixels = 1e9;

  let dorsoidongBlue = image.select(bandName).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: dorsoidongCo,
    scale: scale,
    maxPixels: maxPixels
  });

  let chibzhangBlue = image.select(bandName).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: chibzhangCo,
    scale: scale,
    maxPixels: maxPixels
  });

  const dorsoidongMean = dorsoidongBlue.get(bandName).getInfo();
  const dorsoidongCount = dorsoidongBlue.get(bandName + '_count').getInfo();
  const chibzhangMean = chibzhangBlue.get(bandName).getInfo();
  const chibzhangCount = chibzhangBlue.get(bandName + '_count').getInfo();

  // 5. Validation & Final Answer
  if (dorsoidongCount === 0 || chibzhangCount === 0) {
    console.log(`Dorsoidong Co valid pixels: ${dorsoidongCount}`);
    console.log(`Chibzhang Co valid pixels: ${chibzhangCount}`);
    console.log("No valid pixels remain for one or both lakes after cloud masking.");
    console.log("C2");
    return;
  }

  if (dorsoidongMean === null || chibzhangMean === null) {
    console.log(`Dorsoidong Co Blue mean: ${dorsoidongMean}, Chibzhang Co Blue mean: ${chibzhangMean}`);
    console.log("Calculation resulted in None/NaN for one or both lakes.");
    console.log("C3");
    return;
  }

  console.log(`Dorsoidong Co Blue Reflectance (B1): ${dorsoidongMean.toFixed(4)} (Pixels: ${dorsoidongCount})`);
  console.log(`Chibzhang Co Blue Reflectance (B1): ${chibzhangMean.toFixed(4)} (Pixels: ${chibzhangCount})`);

  if (dorsoidongMean > chibzhangMean) {
    console.log("A"); // Dorsoidong Co is lighter blue (higher reflectance)
  } else {
    console.log("B"); // Chibzhang Co is lighter blue or they are equal
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
